    setup() {
        // Initialize isActive state here
        const isActive = ref(false)

        // Define toggleActive function here
        const toggleActive = () => {
            isActive.value = !isActive.value
        }

        return {
            // Return reactive state and function
            isActive,
            toggleActive
        }
    },
    template: `
        <div>
            <div :class="{ active: isActive }">
                <p>{{ isActive ? 'Active!' : 'Inactive' }}</p>
            </div>
            <button @click="toggleActive">
                <!-- Add descriptive button text here -->
            </button>
        </div>
    `
}

